#include "brauer_adapter.cpp"
struct RBlock {unsigned mask;vector<int> sites;vector<vector<pair<int,int>>> row;};
vector<RBlock> rb;vector<pair<int,array<int,5>>> re;
int shift_site(int i,int t){return ((i/4+t/4)%8)*4+(i%4+t%4)%4;}
unordered_map<unsigned,array<int64_t,15>> memo;
array<int64_t,15> reference_channels(unsigned mask){array<int,6>s;int j=0;for(int i=0;i<32;i++)if(mask>>i&1)s[j++]=i;assert(j==6);array<int64_t,15>a{};for(int p=0;p<15;p++)for(int special=0;special<3;special++){long long v=2;for(int k=0;k<3;k++){int x=s[pairs6[p][2*k]],y=s[pairs6[p][2*k+1]];v*=k==special?cm[orbit[x][y]]:adjmat[x][y];}a[p]+=v;}return a;}
int64_t reference_amplitude(uint64_t state,unsigned mask){array<int,6>col;int n=0;for(unsigned bits=mask;bits;bits&=bits-1){int i=__builtin_ctz(bits);col[n++]=state>>(2*i)&3;}assert(n==6);auto it=memo.find(mask);if(it==memo.end()){if(memo.size()==16384)memo.clear();it=memo.emplace(mask,reference_channels(mask)).first;}int64_t z=0;for(int p=0;p<15;p++){bool yes=true;for(int k=0;k<6;k+=2)if(col[pairs6[p][k]]!=col[pairs6[p][k+1]])yes=false;if(yes)z+=it->second[p];}return z;}
array<I,15> direct(array<int,6>s){unsigned targetmask=0;for(int a:s)targetmask|=1u<<a;array<I,15>out{};for(int p=0;p<15;p++){uint64_t state=0;for(int k=0;k<6;k++)state|=uint64_t(k/2+1)<<(2*s[pairs6[p][k]]);for(auto [bi,sites]:re){auto& b=rb[bi];int local=0;uint64_t outside=state;unsigned outside_mask=targetmask;for(int j=0;j<(int)b.sites.size();j++){local|=((state>>(2*sites[j]))&3)<<(2*j);outside&=~(3ULL<<(2*sites[j]));outside_mask&=~(1u<<sites[j]);}for(auto [src,c]:b.row[local]){uint64_t q=outside;unsigned qmask=outside_mask;for(int j=0;j<(int)b.sites.size();j++){int color=src>>(2*j)&3;q|=uint64_t(color)<<(2*sites[j]);if(color)qmask|=1u<<sites[j];}out[p]+=I(c)*reference_amplitude(q,qmask);}}}return out;}
Indexed load_rules(string path){rb.clear();re.clear();Indexed idx;ifstream f(path,ios::binary);unsigned mask;uint16_t src,dst;int32_t c;while(f.read((char*)&mask,4)){f.read((char*)&src,2);f.read((char*)&dst,2);f.read((char*)&c,4);if(rb.empty()||rb.back().mask!=mask){RBlock b;b.mask=mask;for(int i=0;i<32;i++)if(mask>>i&1)b.sites.push_back(i);b.row.resize(1<<(2*b.sites.size()));rb.push_back(b);}rb.back().row[dst].push_back({src,c});}
for(int bi=0;bi<(int)rb.size();bi++){auto&b=rb[bi];Local l;l.support=b.mask;l.sites=b.sites;l.rows.resize(b.row.size());l.vacuum=0;for(int dst=0;dst<(int)b.row.size();dst++)for(auto[src,c]:b.row[dst])if(src==0&&dst==0)l.vacuum=c;else l.rows[dst].push_back({src,c});idx.blocks.push_back(l);for(int t=0;t<32;t++){array<int,5> ss{};Emb e{};e.block=bi;for(int j=0;j<(int)b.sites.size();j++){ss[j]=shift_site(b.sites[j],t);e.sites[j]=ss[j];e.mask|=1u<<ss[j];}re.push_back({bi,ss});int ei=idx.embeddings.size();idx.embeddings.push_back(e);for(int j=0;j<(int)b.sites.size();j++)idx.incidence[ss[j]].push_back(ei);if(l.vacuum)for(unsigned sub=e.mask;;sub=(sub-1)&e.mask){idx.vacuum_poly[sub]+=l.vacuum*(__builtin_popcount(sub)%2?-1:1);if(!sub)break;}}}for(auto[m,c]:idx.vacuum_poly)if(c){if(m)idx.vacindex[__builtin_ctz(m)].push_back({m,c});else idx.constant=c;}return idx;}
// Independent expansion: enumerate each external pairing color directly into full local columns.
void check_saved_diagrams(string path,string cart){map<unsigned,map<pair<int,int>,long long>> expanded,expected;ifstream f(path,ios::binary);unsigned mask;uint64_t key;int64_t c;long long count=0;while(f.read((char*)&mask,4)){f.read((char*)&key,8);f.read((char*)&c,8);assert(f&&c);count++;int input=key>>40&31,output=key>>45&31;assert(__builtin_popcount(input)==__builtin_popcount(output));assert((key>>50)==0);array<int,10> mates;vector<pair<int,int>> pairs;for(int i=0;i<10;i++){mates[i]=key>>(4*i)&15;bool active=(i<5?input>>(i):output>>(i-5))&1;if(!active)assert(mates[i]==15);else{assert(mates[i]<10&&mates[i]!=i);assert((int(key>>(4*mates[i]))&15)==i);if(i<mates[i])pairs.push_back({i,mates[i]});}}int assignments=1;for(auto pair:pairs)assignments*=3;for(int colors=0;colors<assignments;colors++){int x=colors,a=0,b=0;for(auto [i,j]:pairs){int col=x%3+1;x/=3;for(int leg:{i,j})if(leg<5)a|=col<<(2*leg);else b|=col<<(2*(leg-5));}expanded[mask][{a,b}]+=c;}}
ifstream g(cart,ios::binary);uint16_t a,b;int32_t v;while(g.read((char*)&mask,4)){g.read((char*)&a,2);g.read((char*)&b,2);g.read((char*)&v,4);expected[mask][{a,b}]=v;}for(auto&[m,cols]:expanded)for(auto it=cols.begin();it!=cols.end();)if(it->second==0)it=cols.erase(it);else ++it;assert(expanded==expected);cout<<"Independent expansion records="<<count<<" matches all Cartesian entries\n";}
// Graph traversal independent of union-find; compare every composition for a deterministic suite.
pair<Key,int64_t> graph_compose(Key first,Key second){assert(omask(first)==imask(second));array<vector<int>,15> adj;for(int layer=0;layer<2;layer++){Key k=layer?second:first;for(int i=0;i<10;i++){int j=partner(k,i);if(j<10&&i<j){adj[i+5*layer].push_back(j+5*layer);adj[j+5*layer].push_back(i+5*layer);}}}array<int,10> p;p.fill(15);bool seen[15]{};long long factor=1;for(int i=0;i<15;i++)if(!seen[i]&&!adj[i].empty()){vector<int> stack{i},ext;seen[i]=true;while(!stack.empty()){int v=stack.back();stack.pop_back();if(v<5)ext.push_back(v);else if(v>=10)ext.push_back(v-5);for(int w:adj[v])if(!seen[w]){seen[w]=true;stack.push_back(w);}}assert(ext.size()==0||ext.size()==2);if(ext.empty())factor*=3;else p[ext[0]]=ext[1],p[ext[1]]=ext[0];}return {makekey(imask(first),omask(second),p),factor};}
void check_compositions(){long long comparisons=0;for(int mask=0;mask<32;mask++){set<Key> level{identity(mask)};for(int depth=0;depth<3;depth++){set<Key> next;for(Key k:level)for(int a=0;a<5;a++)for(int b=a+1;b<5;b++)for(int op=0;op<3;op++)for(auto[e,c]:elementary(omask(k),rule::letter(op,a,b))){assert(compose(k,e)==graph_compose(k,e));comparisons++;next.insert(compose(k,e).first);}level=move(next);}}cout<<"Independent graph composition comparisons="<<comparisons<<endl;}
int main(int argc,char**argv){string src=argv[1],cart=argv[2],out=argv[3];rule::outdir=out;rule::deadline=27.;matching({0,1,2,3,4,5},{},0);physical_edge();probes();for(int n=0;n<=32;n++){chooseN[n][0]=1;for(int k=1;k<=6;k++)chooseN[n][k]=n?chooseN[n-1][k-1]+chooseN[n-1][k]:0;}ifstream g(src+"/geometry_8x4.txt");int nr,dim,ne;g>>nr>>dim>>ne;assert(nr==32&&dim==14);for(int k=0;k<ne;k++){int a,b,w;g>>a>>b>>w;adjmat[a][b]=adjmat[b][a]=w;}for(int i=0;i<32;i++)for(int j=i+1;j<32;j++){g>>orbit[i][j];orbit[j][i]=orbit[i][j];}ifstream coeff(src+"/reference_coefficients.txt");long long skip;for(int i=0;i<14;i++)coeff>>skip;for(auto&c:cm)coeff>>c;
check_compositions();small_brauer(out);rule::graph(8,4);for(string fam:{"N","F","L"}){check_saved_diagrams(src+"/run/diagrams_"+fam+".bin",cart+"/run/rules_"+fam+".bin");auto idx=compile_brauer(fam,out,cart+"/run");load_rules(cart+"/run/rules_"+fam+".bin");lazy.clear();memo.clear();long long hits=0;int zero=0;for(int j=0;j<512;j++){auto s=unrank(uint64_t(j)*169910/511);unsigned mask=0;for(int a:s)mask|=1u<<a;auto a=reference_channels(mask);assert(a==analytic(mask));zero+=all_of(a.begin(),a.end(),[](auto x){return x==0;});BC count;auto x=brauer_action(idx,s,count);auto y=direct(s);assert(x==y);hits+=count.diagram_hits;}cout<<fam<<" all 512 x 15 outputs match; zero-source targets="<<zero<<" diagram_hits="<<hits<<" CPU="<<rule::cpu()<<endl;}
rusage r{};getrusage(RUSAGE_SELF,&r);cout<<"CPU="<<rule::cpu()<<" RSS_KiB="<<r.ru_maxrss<<endl;}
